def main()->int:
 d=json.loads(P.read_text(encoding="utf-8"));c={}
 c["schema"]=d.get("schema_version")=="v5.hybrid.h14.preregistration.v1";c["identity"]=d.get("experiment_id")=="H14";c["registered_no_launch"]=d.get("status")=="REGISTERED_NO_LAUNCH"
