 sv=d["single_variable"];c["single_variable"]=sv.get("control")=="MSE" and sv.get("treatment")=="SmoothL1" and sv.get("treatment_beta_raw_bb")==1.0 and sv.get("standard_ppo_critic_loss_both_arms")=="MSE";c["no_outcome_search"]="no CAL-EXT-002" in sv.get("beta_selection","")
