 cfg=d["frozen_common_config"];expected={"target_kl":0.03,"value_head_catchup_after_kl_stop":True,"critic_contract":"critic_v1","value_coef":0.5,"ppo_epochs":4,"mini_batch_size":1024,"workers":22,"rollout_mode":"multi","rollout_envs_per_worker":16,"fixed_training_deal_stream":True,"opponent_assignment":"per-iteration","preflop_action_prior_coef":0.01,"postflop_action_prior_coef":0.02,"optimizer_reset":False};c["common_config"]=all(cfg.get(k)==v for k,v in expected.items());c["allin_ev"]=cfg.get("mirror_self_play_deals") is True and cfg.get("allin_runout_ev") is True and cfg.get("allin_runout_ev_max_runouts")==200
