 g=d["gates"];expected_g={"endpoint_mse_primary_reduction_point_min":0.075,"endpoint_mse_primary_ci95_lower_min":0.0,"source_anchor_degradation_point_max":0.05,"source_anchor_degradation_ci95_upper_max":0.1,"kl_p95_max":0.03,"first60_hps_ratio_min":0.85,"full_hps_ratio_min":0.85,"entropy_median_last200_min":0.3,"entropy_treatment_minus_control_min":-0.1,"mirror_pairs":40000,"mirror_treatment_control_ci95_lower_min_bb100":-20.0,"mirror_treatment_source_ci95_lower_min_bb100":-20.0};c["science_gates"]=all(g.get(k)==v for k,v in expected_g.items())
 j=d["judgment"];c["terminal_verdicts"]=all(k in j for k in ["pass","fail","inconclusive"]) and j.get("route_review_after_fail_or_inconclusive") is True
