 au=d["authority"];c["launch_blocked"]=au.get("launch","").startswith("BLOCKED_UNTIL_H14_");c["official_zero"]=au.get("official_hands")==0;c["no_strength"]=au.get("strength_claim")=="FORBIDDEN";c["holdout_forbidden"]="FORBIDDEN_HOLDOUT_ONLY" in d.get("holdout","")
 failed=sorted(k for k,v in c.items() if not v);out={"schema_version":"v5.hybrid.h14.preregistration_audit.v1","checked_at":datetime.now(timezone.utc).isoformat(),"preregistration_sha256":sha(P),"checks":c,"checks_passed":sum(c.values()),"checks_total":len(c),"failed":failed,"overall":"PASS" if not failed else "FAIL_CLOSED","launch_authority":"NONE_REGISTRATION_AUDIT_ONLY","official_hands":0,"strength_claim":"FORBIDDEN"};OUT.write_text(json.dumps(out,indent=2,sort_keys=True)+"\n",encoding="utf-8");print(json.dumps(out,indent=2,sort_keys=True));return 0 if not failed else 1
